arguments.newString:
/**
 * The two "all icons in one file" bundles the picker's own dialog chrome needs loaded to render every
 * glyph. Must be the full glyph sheet (`icons.css`), not `component-icons.css` — that lean file only
 * carries the handful of `--instui-icon-*` tokens the component CSS itself references, so most icons
 * would have no glyph token defined and render as unmasked, filled squares in the picker.
 */
export const ICON_BUNDLE_CDN_FILES: CdnFile[] = [
  { package: "@pantoken/components", path: "dist/icons.css" },
  { package: "@pantoken/plugin-simple-icons", path: "dist/simple-icons.css" },
];
